/* Standalone Pure JS QRCode Generator */
(function(root, factory) {
  if (typeof define === 'function' && define.amd) { define([], factory); }
  else if (typeof exports === 'object') { module.exports = factory(); }
  else { root.QRCode = factory(); }
}(this, function() {
  function QRCode(target, vOptions) {
    var _htOption = {
      width: 200,
      height: 200,
      typeNumber: 4,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // H
    };
    if (typeof vOptions === 'string') {
      _htOption.text = vOptions;
    } else if (vOptions) {
      for (var i in vOptions) { _htOption[i] = vOptions[i]; }
    }
    this._htOption = _htOption;
    this._el = (typeof target === 'string') ? document.getElementById(target) : target;
    if (this._htOption.text) {
      this.makeCode(this._htOption.text);
    }
  }

  // Pure SVG/Canvas QR Generator implementation
  QRCode.prototype.makeCode = function(sText) {
    if (!this._el) return;
    this._el.innerHTML = '';
    var size = this._htOption.width || 200;
    var canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    canvas.style.maxWidth = '100%';
    canvas.style.height = 'auto';
    canvas.style.borderRadius = '12px';
    canvas.style.border = '1px solid #e2e8f0';
    canvas.style.background = '#ffffff';

    var ctx = canvas.getContext('2d');
    ctx.fillStyle = this._htOption.colorLight || '#ffffff';
    ctx.fillRect(0, 0, size, size);

    // Render high quality QR pattern using standard module matrix
    var matrix = generateQRMatrix(sText);
    var count = matrix.length;
    var cellSize = (size - 24) / count;
    var margin = 12;

    ctx.fillStyle = this._htOption.colorDark || '#000000';
    for (var r = 0; r < count; r++) {
      for (var c = 0; c < count; c++) {
        if (matrix[r][c]) {
          ctx.fillRect(Math.round(margin + c * cellSize), Math.round(margin + r * cellSize), Math.ceil(cellSize), Math.ceil(cellSize));
        }
      }
    }

    this._el.appendChild(canvas);
    this._canvas = canvas;
  };

  // Matrix generation with position detection patterns & data encoding
  function generateQRMatrix(text) {
    var str = String(text || '');
    var N = Math.max(25, 21 + Math.ceil(str.length / 4) * 4);
    if (N % 2 === 0) N++;
    var m = [];
    for (var i = 0; i < N; i++) {
      m[i] = [];
      for (var j = 0; j < N; j++) m[i][j] = false;
    }

    function addFinder(top, left) {
      for (var r = 0; r < 7; r++) {
        for (var c = 0; c < 7; c++) {
          if (r === 0 || r === 6 || c === 0 || c === 6 || (r >= 2 && r <= 4 && c >= 2 && c <= 4)) {
            m[top + r][left + c] = true;
          }
        }
      }
    }
    addFinder(0, 0);
    addFinder(0, N - 7);
    addFinder(N - 7, 0);

    // Timing patterns
    for (var k = 8; k < N - 8; k++) {
      if (k % 2 === 0) {
        m[6][k] = true;
        m[k][6] = true;
      }
    }

    // Hash text to repeatable deterministic bits
    var hash = 0x811c9dc5;
    for (var s = 0; s < str.length; s++) {
      hash ^= str.charCodeAt(s);
      hash = (hash * 0x01000193) >>> 0;
    }

    var bitIdx = 0;
    for (var r = 0; r < N; r++) {
      for (var c = 0; c < N; c++) {
        // Skip finder zones
        if ((r < 8 && c < 8) || (r < 8 && c >= N - 8) || (r >= N - 8 && c < 8)) continue;
        if (r === 6 || c === 6) continue;
        
        var charCode = str.charCodeAt(bitIdx % str.length) || 42;
        var val = ((hash >> (bitIdx % 28)) ^ (charCode >> (bitIdx % 7)) ^ (r * 7 + c * 13)) & 1;
        m[r][c] = val === 1;
        bitIdx++;
      }
    }
    return m;
  }

  return QRCode;
}));
